#include <stdio.h>
struct S1 { char c; int i; };
struct S2 { char c; char d; };
struct S3 { double d; char c; int i; };
int main() {
    printf("sizeof S1: %d\n", (int)sizeof(struct S1));
    printf("sizeof S2: %d\n", (int)sizeof(struct S2));
    printf("sizeof S3: %d\n", (int)sizeof(struct S3));
    return 0;
}
